class Container:
    def __init__(self, m, kap):
        self._m = m
        self._kap = kap
        self._fyll = 0

    def grad(self):
        return self._fyll * 100 // self._kap

    def ta_imot(self, kilo):
        if self._fyll + kilo > self._kap:
            print("Ikke plass i", self._m)
        else:
            self._fyll = self._fyll + kilo

c = Container("glass", 200)
c.ta_imot(60)
c.ta_imot(160)
print(c.grad())
